import{_ as l,C as d,o as e,c as i,E as r,a1 as a,b as u,w as o,a as h,a2 as p}from"./chunks/framework.NjEjlYNI.js";const f=JSON.parse('{"title":"缺陷管理","description":"缺陷管理全流程 — Bug 定义、生命周期（new→open→fix→verify→close+reopen）、严重程度 vs 优先级、缺陷报告 10 要素、质量指标、禅道/JIRA 实战","frontmatter":{"title":"缺陷管理","description":"缺陷管理全流程 — Bug 定义、生命周期（new→open→fix→verify→close+reopen）、严重程度 vs 优先级、缺陷报告 10 要素、质量指标、禅道/JIRA 实战","difficulty":"intermediate","frequency":"high"},"headers":[],"relativePath":"testing/defect-management.md","filePath":"testing/defect-management.md"}'),g={name:"testing/defect-management.md"};function c(E,t,b,q,A,B){const n=d("DifficultyBadge"),s=d("Mermaid");return e(),i("div",null,[r(n,{level:"intermediate"}),t[1]||(t[1]=a('<h1 id="缺陷管理" tabindex="-1">缺陷管理 <a class="header-anchor" href="#缺陷管理" aria-label="Permalink to &quot;缺陷管理&quot;">​</a></h1><h2 id="一句话解释" tabindex="-1">一句话解释 <a class="header-anchor" href="#一句话解释" aria-label="Permalink to &quot;一句话解释&quot;">​</a></h2><p>缺陷管理是对 bug 从&quot;被发现&quot;到&quot;被关闭&quot;<strong>全生命周期的记录、跟踪、分析和闭环管理</strong>。测试人员的核心产出物之一就是<strong>高质量的缺陷报告</strong>——同一个 bug，写得好，开发 5 分钟就修；写得烂，开发拖三天还来质问你。<strong>&quot;会找 bug&quot;和&quot;会写 bug&quot;是两种能力，后者决定你被不被尊重。</strong></p><h2 id="核心流程-bug-生命周期" tabindex="-1">核心流程：Bug 生命周期 <a class="header-anchor" href="#核心流程-bug-生命周期" aria-label="Permalink to &quot;核心流程：Bug 生命周期&quot;">​</a></h2>',4)),(e(),u(p,null,{default:o(()=>[r(s,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E6%B5%8B%E8%AF%95%E5%8F%91%E7%8E%B0%E7%BC%BA%E9%99%B7%22%5D%20--%3E%20B%5B%22New%20%E6%96%B0%E5%BB%BA%22%5D%0A%20%20%20%20B%20--%3E%20C%7B%22%E5%BC%80%E5%8F%91%E7%A1%AE%E8%AE%A4%22%7D%0A%20%20%20%20C%20--%3E%7C%22%E7%A1%AE%E8%AE%A4%E6%9C%89%E6%95%88%22%7C%20D%5B%22Open%20%E6%89%93%E5%BC%80%3Cbr%2F%3E%E6%8C%87%E6%B4%BE%E5%BC%80%E5%8F%91%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E6%97%A0%E6%95%88%20%E9%9C%80%E6%B1%82%E6%9C%AC%E5%A6%82%E6%AD%A4%22%7C%20E%5B%22Rejected%20%E6%8B%92%E7%BB%9D%3Cbr%2F%3E%E6%B5%8B%E8%AF%95%E9%9C%80%E5%9B%9E%E5%BA%94%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E4%B8%8E%E5%B7%B2%E6%9C%89%20bug%20%E9%87%8D%E5%A4%8D%22%7C%20F%5B%22Duplicate%20%E9%87%8D%E5%A4%8D%3Cbr%2F%3E%E5%85%B3%E8%81%94%E4%B8%BB%20bug%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E5%BD%93%E5%89%8D%E7%89%88%E6%9C%AC%E4%B8%8D%E6%94%B9%22%7C%20G%5B%22Deferred%20%E5%BB%B6%E5%90%8E%3Cbr%2F%3E%E9%9C%80%20PM%20%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20%20%20D%20--%3E%20H%5B%22Fix%20%E4%BF%AE%E5%A4%8D%E5%AE%8C%E6%88%90%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%22Verify%20%E5%9B%9E%E5%BD%92%E9%AA%8C%E8%AF%81%22%5D%0A%20%20%20%20I%20--%3E%7C%22%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%22%7C%20J%5B%22Close%20%E5%85%B3%E9%97%AD%22%5D%0A%20%20%20%20I%20--%3E%7C%22%E9%AA%8C%E8%AF%81%E6%9C%AA%E9%80%9A%E8%BF%87%22%7C%20D%0A%20%20%20%20J%20-.-%3E%7C%22%E5%9B%9E%E5%BD%92%E4%B8%AD%E5%86%8D%E6%AC%A1%E5%87%BA%E7%8E%B0%22%7C%20K%5B%22Reopen%20%E9%87%8D%E6%96%B0%E6%89%93%E5%BC%80%22%5D%0A%20%20%20%20K%20--%3E%20D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[h(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a(`<blockquote><p><strong>记忆锚点</strong>：一条主线 <code>new → open → fix → verify → close</code>，两个旁路 <code>reopen</code>（关闭后复发）和 <code>rejected/duplicate/deferred</code>（开发侧的各种&quot;不修&quot;）。面试画这张图，比背定义有用得多。</p></blockquote><h2 id="深入理解" tabindex="-1">深入理解 <a class="header-anchor" href="#深入理解" aria-label="Permalink to &quot;深入理解&quot;">​</a></h2><h3 id="_1-什么是-bug" tabindex="-1">1. 什么是 Bug <a class="header-anchor" href="#_1-什么是-bug" aria-label="Permalink to &quot;1. 什么是 Bug&quot;">​</a></h3><p><strong>定义</strong>：软件在运行中出现的不符合需求文档、设计文档、用户预期或行业标准的行为。注意&quot;不符合用户预期&quot;也算——需求没写但不合理，同样要提。</p><p><strong>相关术语别混：</strong></p><table tabindex="0"><thead><tr><th>术语</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td>Error（错误）</td><td>人为产生的代码错误</td><td>程序员把 <code>&gt;</code> 写成了 <code>&lt;</code></td></tr><tr><td>Defect / Bug（缺陷）</td><td>Error 导致产品中的问题</td><td>年龄 17 岁被放行注册</td></tr><tr><td>Fault（故障点）</td><td>导致失败的具体缺陷位置</td><td>某一行年龄判断逻辑</td></tr><tr><td>Failure（故障）</td><td>缺陷被执行时暴露的现象</td><td>用户提交报错、页面白屏</td></tr></tbody></table><p><strong>缺陷从哪来（按来源排序）：</strong></p><table tabindex="0"><thead><tr><th>来源</th><th>占比（经验值）</th><th>说明</th></tr></thead><tbody><tr><td>需求问题</td><td>高</td><td>需求模糊、歧义、需求变更</td></tr><tr><td>设计缺陷</td><td>中</td><td>架构/交互设计考虑不周</td></tr><tr><td>编码错误</td><td>中</td><td>逻辑写错、边界没判断</td></tr><tr><td>环境/配置</td><td>中</td><td>依赖版本、服务器配置、数据问题</td></tr><tr><td>兼容性</td><td>低</td><td>不同浏览器/机型表现不同</td></tr></tbody></table><blockquote><p><strong>转岗优势</strong>：你能看代码，发现 bug 时可以先&quot;定位到模块甚至文件&quot;，直接把&quot;前端 bug 还是后端 bug&quot;分清楚——这对测试岗是稀缺能力。</p></blockquote><h3 id="_2-bug-生命周期各状态" tabindex="-1">2. Bug 生命周期各状态 <a class="header-anchor" href="#_2-bug-生命周期各状态" aria-label="Permalink to &quot;2. Bug 生命周期各状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>负责人</th><th>触发动作</th></tr></thead><tbody><tr><td>New</td><td>新建，等待确认</td><td>测试</td><td>提交缺陷报告</td></tr><tr><td>Open</td><td>确认有效，指派开发</td><td>测试/开发组长</td><td>开发确认、指派人</td></tr><tr><td>Rejected</td><td>拒绝（不是 bug）</td><td>开发</td><td>给出理由，测试需确认是否接受</td></tr><tr><td>Duplicate</td><td>与已有缺陷重复</td><td>开发</td><td>关联到主 bug 后关闭</td></tr><tr><td>Deferred</td><td>延后到后续版本</td><td>PM</td><td>评估后定版本</td></tr><tr><td>Fix</td><td>开发已修复</td><td>开发</td><td>提交修复代码</td></tr><tr><td>Verify</td><td>回归验证中</td><td>测试</td><td>执行回归用例</td></tr><tr><td>Close</td><td>验证通过，关闭</td><td>测试</td><td>验证通过</td></tr><tr><td>Reopen</td><td>关闭后复发，重新打开</td><td>测试</td><td>回归中发现同问题</td></tr></tbody></table><p><strong>容易踩的坑：</strong></p><ul><li><strong>Rejected 不是终结</strong>：开发拒绝后，测试要重新确认是&quot;需求如此&quot;还是&quot;开发没理解需求&quot;。被拒也要回应、要有结论，不能放着不管。</li><li><strong>Reopen 要理直气壮</strong>：开发说&quot;我修好了&quot;，你验证没通过就是没通过，<strong>回退到 Open 是正常流程</strong>，不是给开发难堪。</li><li><strong>Close 的标准</strong>：不只复现步骤通过，还要做<strong>回归</strong>——确认修复没有引入新问题。</li></ul><h3 id="_3-严重程度-vs-优先级" tabindex="-1">3. 严重程度 vs 优先级 <a class="header-anchor" href="#_3-严重程度-vs-优先级" aria-label="Permalink to &quot;3. 严重程度 vs 优先级&quot;">​</a></h3><p><strong>严重程度（对产品的伤害有多大）——客观属性：</strong></p><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td>S0</td><td>致命 / Critical</td><td>崩溃、数据丢失、资损、安全漏洞</td><td>转账金额多打一个零</td></tr><tr><td>S1</td><td>严重 / Major</td><td>主功能不可用，无绕过方案</td><td>登录接口 500</td></tr><tr><td>S2</td><td>一般 / Minor</td><td>功能可用但不符合预期，有绕过方案</td><td>筛选条件漏掉一项</td></tr><tr><td>S3</td><td>轻微 / Trivial</td><td>不影响功能的细节问题</td><td>文案错字、颜色不统一</td></tr></tbody></table><p><strong>优先级（什么时候修）——主观决策：</strong></p><table tabindex="0"><thead><tr><th>级别</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td>P0</td><td>立即修，阻塞发布</td><td>用户无法登录</td></tr><tr><td>P1</td><td>高，本次版本必须修</td><td>核心流程报错</td></tr><tr><td>P2</td><td>中，尽量修，可排期</td><td>非核心功能异常</td></tr><tr><td>P3</td><td>低，有空再修</td><td>界面小瑕疵</td></tr></tbody></table><p><strong>两者不是一回事：</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>严重程度</th><th>优先级</th><th>为什么</th></tr></thead><tbody><tr><td>银行转账金额显示少一位</td><td>S0 致命</td><td>P0</td><td>资损，最严重</td></tr><tr><td>登录功能偶发 500</td><td>S1 严重</td><td>P1</td><td>主流程，必须本次版本修</td></tr><tr><td>结算页优惠券按钮文字&quot;0领取&quot;</td><td>S3 轻微</td><td>P1</td><td>促销页面，影响转化率，虽不严重但优先级高</td></tr><tr><td>极端低频场景下的数据错乱</td><td>S1 严重</td><td>P3</td><td>严重但几乎触发不到，可延后</td></tr></tbody></table><blockquote><p><strong>面试必答</strong>：严重程度是&quot;bug 对产品的客观伤害&quot;，开发定；优先级是&quot;什么时候修的主观决策&quot;，测试/PM 定。<strong>高严重 ≠ 高优先级</strong>（低频但致命）<strong>，低严重 ≠ 低优先级</strong>（影响营收的文案错）。</p></blockquote><h3 id="_4-缺陷报告-10-要素" tabindex="-1">4. 缺陷报告 10 要素 <a class="header-anchor" href="#_4-缺陷报告-10-要素" aria-label="Permalink to &quot;4. 缺陷报告 10 要素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>要素</th><th>写好要点</th></tr></thead><tbody><tr><td>1</td><td>标题</td><td>一句话：<strong>模块 + 操作 + 结果</strong>，如&quot;结算页：提交订单偶发 500&quot;</td></tr><tr><td>2</td><td>缺陷编号</td><td>系统自动生成，聊天里引用它即可</td></tr><tr><td>3</td><td>严重程度 / 优先级</td><td>S0-S3 / P0-P3</td></tr><tr><td>4</td><td>环境信息</td><td>浏览器、版本、操作系统、设备、网络</td></tr><tr><td>5</td><td>前置条件</td><td>测试前必须满足的状态</td></tr><tr><td>6</td><td>复现步骤</td><td>精确到每一步，能被人<strong>照做复现</strong></td></tr><tr><td>7</td><td>预期结果</td><td>软件应该怎样</td></tr><tr><td>8</td><td>实际结果</td><td>软件实际怎样</td></tr><tr><td>9</td><td>证据</td><td>截图、录屏、Console 报错、Network 请求、日志</td></tr><tr><td>10</td><td>附加信息</td><td>出现频率（必现/偶发）、涉及版本号、责任人</td></tr></tbody></table><p><strong>一份合格的缺陷报告长这样：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【标题】结算页：点击&quot;提交订单&quot;偶发 500，订单无法生成</span></span>
<span class="line"><span>【模块】购物车-结算</span></span>
<span class="line"><span>【严重程度】S1 严重　　【优先级】P1</span></span>
<span class="line"><span>【环境】Chrome 126 / macOS 14 / 正式环境</span></span>
<span class="line"><span>【前置条件】购物车已有 3 件商品，总价 ¥299.00</span></span>
<span class="line"><span>【复现步骤】</span></span>
<span class="line"><span>  1. 登录后进入购物车</span></span>
<span class="line"><span>  2. 点击&quot;去结算&quot;进入结算页</span></span>
<span class="line"><span>  3. 选择默认收货地址，点击&quot;提交订单&quot;</span></span>
<span class="line"><span>  4. 页面白屏并弹出 500 错误</span></span>
<span class="line"><span>【预期结果】提交成功，跳转支付页</span></span>
<span class="line"><span>【实际结果】白屏 500，刷新后购物车商品仍在（未生成订单）</span></span>
<span class="line"><span>【出现频率】5 次复现 3 次（偶发）</span></span>
<span class="line"><span>【证据】见附件 console-500.png、network 返回 500 的 request 日志</span></span></code></pre></div><blockquote><p><strong>前端转测加分项</strong>：附上 Console 报错栈、Network 里请求和响应的 status、是 <code>4xx</code> 还是 <code>5xx</code>。这一条就能让开发把你的 bug 优先级手动拉高——因为&quot;你替他做了一半定位&quot;。</p></blockquote><p><strong>书写三原则：</strong> ① 标题能看懂即可，别写&quot;有问题&quot;三个字；② 复现步骤<strong>照做一定能复现</strong>；③ 证据永远比描述更有说服力，截图录屏管够。</p><h3 id="_5-缺陷密度与质量指标" tabindex="-1">5. 缺陷密度与质量指标 <a class="header-anchor" href="#_5-缺陷密度与质量指标" aria-label="Permalink to &quot;5. 缺陷密度与质量指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>公式 / 含义</th><th>用途</th></tr></thead><tbody><tr><td>缺陷密度</td><td>缺陷总数 ÷ 千行代码（KLOC）或功能点</td><td>衡量模块质量，密度越高越该重构</td></tr><tr><td>用例通过率</td><td>通过用例数 ÷ 总执行用例数</td><td>版本发布就绪信号</td></tr><tr><td>缺陷漏测率（逃逸率）</td><td>线上缺陷 ÷（测试发现 + 线上发现）</td><td><strong>衡量测试有效性</strong>，越低越好</td></tr><tr><td>缺陷修复率</td><td>已修复缺陷 ÷ 应修复缺陷</td><td>发布前必修指标，一般要求 100%</td></tr><tr><td>平均修复时长</td><td>总修复时长 ÷ 缺陷数</td><td>团队响应效率</td></tr><tr><td>缺陷解决率</td><td>已解决 ÷ 总数</td><td>衡量遗留风险</td></tr></tbody></table><p><strong>两个最重要的指标：</strong></p><ul><li><strong>缺陷密度</strong>：面试问&quot;如何评估模块质量&quot;就答它——缺陷密集的模块，后续还会出问题，需要重点回归甚至重构。</li><li><strong>缺陷漏测率（逃逸率）</strong>：线上被用户发现的 bug ÷ 全部 bug。转岗面试问&quot;测试的价值怎么衡量&quot;，答这个最有说服力——<strong>它直接反映你上线的产品质量</strong>。</li></ul><h3 id="_6-缺陷管理工具-禅道-vs-jira" tabindex="-1">6. 缺陷管理工具：禅道 vs JIRA <a class="header-anchor" href="#_6-缺陷管理工具-禅道-vs-jira" aria-label="Permalink to &quot;6. 缺陷管理工具：禅道 vs JIRA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>禅道</th><th>JIRA</th></tr></thead><tbody><tr><td>定位</td><td>项目管理 + 需求 + 用例 + 缺陷一体化</td><td>项目协作 + 缺陷跟踪，插件生态强</td></tr><tr><td>开源/费用</td><td>国产开源，低成本，中小公司常用</td><td>国际商业，按用户数收费，大厂/外企常用</td></tr><tr><td>工作流</td><td>内置固定流程，可配置</td><td>自定义工作流极强，可拖拽搭建</td></tr><tr><td>用例管理</td><td>内置测试用例库</td><td>需插件（Xray / Zephyr）</td></tr><tr><td>缺陷字段</td><td>内置，够用</td><td>字段高度自定义</td></tr><tr><td>学习成本</td><td>低，上手快</td><td>中高，术语体系不同</td></tr></tbody></table><p><strong>实操要点（通用能力，工具换了也一样）：</strong></p><ul><li>禅道：<code>测试 → 提Bug</code> 页面，必填项先填全；关联&quot;需求&quot;和&quot;用例&quot;，评审、指派、抄送一条龙。</li><li>JIRA：用 <code>Bug</code> 问题类型，记得设 <code>Sprint</code> 和 <code>Fix Version</code>，让 bug 落在迭代节奏里。</li><li>通用：<strong>改状态必须带评论</strong>（&quot;已修复，请验证 2.0&quot;），不然团队不知道发生了什么；每天下班前过一遍自己名下未关闭的 bug。</li></ul><h2 id="面试问法" tabindex="-1">面试问法 <a class="header-anchor" href="#面试问法" aria-label="Permalink to &quot;面试问法&quot;">​</a></h2><ul><li><p>🔥 <strong>Bug 的生命周期有哪些状态？</strong></p><ul><li>主线 <code>new → open → fix → verify → close</code>，加 <code>reopen</code>（复发）</li><li>旁路：<code>rejected</code>（拒绝）/ <code>duplicate</code>（重复）/ <code>deferred</code>（延后）</li></ul></li><li><p>🔥 <strong>严重程度和优先级的区别？举例说明</strong></p><ul><li>严重程度看客观伤害（S0-S3），优先级看什么时候修（P0-P3）</li><li>例子：支付按钮文案&quot;0领取&quot;严重程度 S3，但因为是活动页影响转化，优先级可以定 P1</li></ul></li><li><p>🔥 <strong>一个合格的缺陷报告要包含哪些要素？</strong></p><ul><li>标题、环境、前置条件、复现步骤、预期结果、实际结果、证据、频率、严重程度/优先级</li></ul></li><li><p>⭐ <strong>如何评估测试质量？有哪些指标？</strong></p><ul><li>缺陷密度（模块质量）、用例通过率（就绪信号）、<strong>缺陷漏测率/逃逸率</strong>（测试有效性）</li></ul></li><li><p>⭐ <strong>禅道和 JIRA 的区别？</strong></p><ul><li>禅道：国产开源、用例缺陷一体化、中小公司；JIRA：商业、自定义工作流强、大厂外企</li></ul></li><li><p>⭐ <strong>开发拒绝了你提的 bug，你怎么办？</strong></p><ul><li>先确认&quot;不是 bug&quot;还是&quot;开发没理解需求&quot;；需求歧义找 PM 仲裁，是自己的问题就撤，开发有误就带着需求文档说服</li></ul></li></ul><h2 id="💡-ai-辅助学习" tabindex="-1">💡 AI 辅助学习 <a class="header-anchor" href="#💡-ai-辅助学习" aria-label="Permalink to &quot;💡 AI 辅助学习&quot;">​</a></h2><blockquote><p>用这个 Prompt 练测试思维： &quot;你扮演一位开发工程师，我扮演测试。我依次给你发 5 份缺陷报告（我先自己写），你从<strong>开发视角</strong>严格点评：哪些信息让你心塞不想修、哪些信息让你愿意立刻处理，指出每份报告缺了 10 要素里的哪几项。第 5 轮之后，你出题：让我写一份关于&#39;支付成功后订单列表未刷新&#39;的缺陷报告，写完你按 10 要素逐条打分，满分 100 分并给出改进意见。全程中文。&quot;</p></blockquote><h3 id="🤖-ai-输出成果-基于上面这个-prompt-生成" tabindex="-1">🤖 AI 输出成果（基于上面这个 Prompt 生成） <a class="header-anchor" href="#🤖-ai-输出成果-基于上面这个-prompt-生成" aria-label="Permalink to &quot;🤖 AI 输出成果（基于上面这个 Prompt 生成）&quot;">​</a></h3><blockquote><p>下面三件套就是 AI 基于上面这个 Prompt 实际生成的测试学习资源，点击后在新窗口打开、可离线使用：</p></blockquote><ul><li>📄 <a href="../qa-cheatsheet.pdf" target="_blank" rel="noopener">测试岗位 A4 速查 PDF</a> — 缺陷报告 10 要素一页速记</li><li>🎬 <a href="../qa-demo.html" target="_blank" rel="noopener">测试交互式演示</a> — 跟着演示走一遍 Bug 生命周期</li><li>📝 <a href="../qa-quiz.html" target="_blank" rel="noopener">测试 Mini Quiz</a> — 严重程度 vs 优先级自测题</li></ul><h2 id="关联知识" tabindex="-1">关联知识 <a class="header-anchor" href="#关联知识" aria-label="Permalink to &quot;关联知识&quot;">​</a></h2><ul><li><a href="./test-case-design.html">测试用例设计</a> — 用例是发现 bug 的起点，缺陷是用例的产出</li><li><a href="./test-basics.html">软件测试基础</a> — 测试流程中&quot;缺陷跟踪&quot;环节的深化</li><li><a href="./interface-testing.html">接口测试</a> — 接口层 bug 的定位与证据收集</li><li><a href="./test-ci-strategy.html">测试策略与 CI/CD</a> — 缺陷漏测率如何靠流程和自动化压下来</li></ul>`,44))])}const m=l(g,[["render",c]]);export{f as __pageData,m as default};
